/// Slot 0x1a8 (`FUN_1416136f0`) of player `p`: `count` objects of master `master` (Gaia's when
/// the player lacks it) at each of its built objects of building master `at` (state 2, in its
/// list's order), up to attribute 234's count of buildings when above 0, in a playback (the
/// screen's mode is not 4). Each object: a male villager (0x53) draws its sex from the Player
/// stream ("SpawnObject": `r % 100` above 49 a female, 0x125); the owner's slot 0x1c0 makes
/// it at the building's place with its flag ([`World::make_new_object`]); its slot 0x1a0 takes
/// it into the building where the building has room for one more (slot 0x198,
/// [`World::has_room`]); unless the player's attribute 283 is above 0 it comes out at once
/// toward no point (`FUN_1411e7220`, [`World::let_out`]); a relic (0x11d) counts in the
/// world's `+0x844` ([`World::spawned_relics`]). The local player's statistics of effect
/// 0x318's spawns are not simulation.
pub(super) fn spawn_at(
    &mut self,
    p: usize,
    master: i16,
    at: i16,
    count: i16,
) -> Result<(), GenieError> {
    /// The male and female villagers' masters.
    const MALE_VILLAGER: i16 = 0x53;
    const FEMALE_VILLAGER: i16 = 0x125;
    /// The relic's master, which the world counts.
    const RELIC: i16 = 0x11d;
    let has = |q: usize, id: i16| self.masters.get(q).is_some_and(|m| m.get(id).is_some());
    let building = self
        .masters
        .get(p)
        .and_then(|m| m.get(at))
        .is_some_and(|m| m.kind == master_type::BUILDING);
    if !building || !(has(p, master) || has(0, master)) || count <= 0 {
        return Ok(());
    }
    let owner = if has(p, master) { p } else { 0 };
    let attribute =
        |q: &crate::world::Player, i: usize| q.attributes.get(i).copied().unwrap_or(0.0);
    let limit = attribute(&self.players[p], 234) as i32;
    let buildings: Vec<i32> = self.players[p]
        .objects
        .iter()
        .filter(|u| u.life.master_id == at && u.life.state == 2)
        .map(|u| u.id)
        .collect();
    for (k, &b) in buildings.iter().enumerate() {
        if 0 < limit && limit <= k as i32 {
            return Ok(());
        }
        for _ in 0..count {
            let made = if master == MALE_VILLAGER {
                let r = self.streams.get(Stream::Player).rand15() as i32;
                if 49 < r % 100 {
                    FEMALE_VILLAGER
                } else {
                    MALE_VILLAGER
                }
            } else {
                master
            };
            let Some((_, building)) = self.object(b) else {
                break;
            };
            let position = building.position;
            let Some(new) = self.make_new_object(owner, made, position, true)? else {
                continue;
            };
            let Some((bp, bu)) = self.object(b) else {
                break;
            };
            if self.has_room(bp, bu, None)? {
                let Some(crate::orders::Place::Live(np, ni)) = self.place(new) else {
                    continue;
                };
                self.enter_forced(np, ni, b)?;
            }
            if attribute(&self.players[p], 283) <= 0.0 {
                let Some(crate::orders::Place::Live(bp, bi)) = self.place(b) else {
                    break;
                };
                let _ = self.let_out(bp, bi, new, [-1.0, -1.0], (None, false))?;
            }
            if master == RELIC {
                self.spawned_relics += 1;
            }
        }
    }
    Ok(())

/// The player's slot 0x1c0 (`FUN_14162ce00`) for `master` at `at`: the master's slot 0x40
/// makes the object (none for a master the player has not got, `FUN_141666a60`); with its
/// flag its footprint is cleared with `param_6` ([`crate::world::World::clear_footprint`]) and
/// a building is worked 10000 seconds at once ([`crate::world::World::work_building`]: a stack
/// unit completes there); a master that gathers by itself joins the visible-resource lists
/// ([`crate::world::World::made_new_object`]). The editor's part (mode 4) never runs in a game.
/// Its id.
///
/// # Errors
///
/// What the parts do not model ([`crate::world::World::combat_object`],
/// [`crate::world::World::plain_object`], [`crate::world::World::make_building`]).
pub(crate) fn make_new_object(
    &mut self,
    p: usize,
    master: i16,
    at: [f32; 3],
    flagged: bool,
) -> Result<Option<i32>, GenieError> {
    let Some(made) = self.masters.get(p).and_then(|m| m.get(master)).cloned() else {
        return Ok(None);
    };
    // a combat unit (type 70, an effect's spawn): the master's slot 0x40 there, its footprint
    // cleared with the flag, its visible resources for one that gathers by itself
    if made.kind == crate::garrison::COMBAT_KIND {
        let idx = self.combat_object(p, master, &made, at)?;
        let id = self.players[p].objects[idx].id;
        if flagged {
            self.clear_footprint(p, master, [at[0], at[1]], true)?;
        }
        if made.auto_gather {
            self.made_new_object(p)?;
        }
        return Ok(Some(id));

